import type { TargetUx } from '../planning/target-ux.js';
import { mermaidLabel } from './mermaid-label.js';

// RF-626, RF-508, DEC-134: the target screen map, a Mermaid flowchart generated by code from the
// checked screens; the model never writes Mermaid. One node per legacy screen card (`l1`, `l2`,
// ... in card order) and one per target screen (`t1`, ...), the decision on the edge between them
// (a dropped screen points to one `Dropped` node), and an edge between target screens where the
// legacy screens lead to each other. Node ids are generated, never taken from the code; `mask`
// hides secrets in every label before `mermaidLabel` codes it; no node gets a click, a link or a
// style.

type Mask = (text: string) => string;

function legacyNodes(ux: TargetUx, mask: Mask): string[] {
  return ux.legacy.map((screen, index) => {
    const name = screen.route === '' ? screen.title : screen.route;
    return `  l${String(index + 1)}["${mermaidLabel(mask(`${screen.cardId}: ${name}`))}"]`;
  });
}

function decisionEdges(ux: TargetUx, targets: ReadonlyMap<string, string>): string[] {
  return ux.legacy.map((screen, index) => {
    const from = `l${String(index + 1)}`;
    const to = screen.target === null ? undefined : targets.get(screen.target);
    return to === undefined
      ? `  ${from} -.->|dropped| d1`
      : `  ${from} -->|${screen.disposition}| ${to}`;
  });
}

function navigationEdges(ux: TargetUx, targets: ReadonlyMap<string, string>): Set<string> {
  const edges = new Set<string>();
  for (const screen of ux.screens) {
    for (const link of screen.navigation) {
      const from = targets.get(screen.id);
      const to = link.screenId === null ? undefined : targets.get(link.screenId);
      if (from !== undefined && to !== undefined) edges.add(`  ${from} --> ${to}`);
    }
  }
  return edges;
}

// RF-626
export function targetScreenMap(ux: TargetUx, mask: Mask): string {
  if (ux.legacy.length === 0) return 'flowchart LR\n';
  const targets = new Map(ux.screens.map((screen, index) => [screen.id, `t${String(index + 1)}`]));
  const screens = ux.screens.map(
    (screen) => `  ${targets.get(screen.id) ?? ''}["${mermaidLabel(mask(screen.name))}"]`,
  );
  const dropped = ux.legacy.some((screen) => screen.target === null) ? ['  d1["Dropped"]'] : [];
  return [
    ...['flowchart LR', ...legacyNodes(ux, mask), ...screens, ...dropped],
    ...decisionEdges(ux, targets),
    ...navigationEdges(ux, targets),
    '',
  ].join('\n');
}
